-- 5. 问答对种子数据 (qa_pairs)
-- 新增 sync_status 和 synced_at 字段
-- ----------------------------
INSERT INTO qa_pairs (id, question, answer, answer_brief, source_doc_id, category, tags, status, confidence, multi_dimensional, sync_status, synced_at, created_at, updated_at) VALUES
('QA20260701001', 'J7卡车DPF灯亮了怎么办？还能继续开吗？', '当DPF报警灯亮起时，说明DPF中积碳已达到需要再生的程度。处理方案：1. 动力正常时可继续行驶但应尽快DPF再生；2. 降低车速至80km/h以下；3. 前往最近服务站强制再生；4. 动力明显下降或伴有发动机故障灯，立即靠边停车并联系救援。', 'DPF灯亮应尽快再生处理，降低车速前往服务站，不可长期无视。', 'DOC20260702003', '故障处理', '["DPF","颗粒捕集器","再生","J7"]', 'PUBLISHED', 0.9520, '{"vehicleModels":["J7","J6P","JH6"],"difficulty":"中等"}', 'SYNCED', '2026-07-15 08:00:00', '2026-06-20 09:30:00', '2026-07-01 10:00:00'),

('QA20260701002', '解放卡车10万公里大保养需要做哪些项目？', '10万公里大保养项目：1. 更换发动机机油和机滤；2. 更换柴油滤芯(粗滤+精滤)；3. 更换空滤；4. 更换变速箱油和后桥齿轮油；5. 检查调整气门间隙；6. 检查刹车片；7. 检查转向和悬挂系统；8. 检查T-Box终端。费用约3500-5000元，耗时3-4小时。', '10万公里保养包含机油三滤、变速箱油、后桥油、气门间隙等，费用3500-5000元。', 'DOC20260702004', '保养维修', '["保养","10万公里","大保养","费用"]', 'PUBLISHED', 0.9380, '{"vehicleModels":["J7","J6P","JH6","鹰途"],"difficulty":"简单"}', 'SYNCED', '2026-07-15 08:30:00', '2026-06-22 14:00:00', '2026-07-02 08:30:00'),

('QA20260702003', 'T-Box设备离线了怎么恢复？', 'T-Box离线恢复：1. 确认车辆是否在信号弱区域；2. 检查电瓶电压(>24V)；3. 熄火5分钟后重新通电；4. 平台远程重启；5. 仍无效则远程固件升级或服务站检测。常见原因：SIM卡欠费、天线松动、固件过低、电源故障。', 'T-Box离线先确认信号和电源，可远程重启或升级固件，无法恢复需服务站检测。', 'DOC20260701002', '终端设备', '["T-Box","离线","远程诊断","固件升级"]', 'PUBLISHED', 0.9210, '{"vehicleModels":["全系"],"difficulty":"中等"}', 'SYNCED', '2026-07-16 09:00:00', '2026-06-25 10:00:00', '2026-07-03 09:00:00'),

('QA20260703004', '如何通过车队管理平台查看车辆油耗分析？', '油耗分析步骤：1. 登录平台(PC/APP)；2. 左侧导航选[油耗管理]；3. 选择维度：单车/车队/月度趋势；4. 选择时间范围；5. 查看百公里油耗曲线、怠速油耗占比；6. 支持导出PDF/Excel报表。平台提供油耗异常自动告警。', '登录平台→油耗管理→选择车辆和时间→查看曲线和统计→导出报表。', 'DOC20260703005', '平台操作', '["油耗分析","车队管理","平台操作"]', 'PUBLISHED', 0.8950, '{"vehicleModels":["全系"],"difficulty":"简单"}', 'NOT_SYNCED', NULL, '2026-06-28 15:00:00', '2026-07-04 11:00:00'),

('QA20260704005', '国六SCR系统故障怎么排查？', 'SCR系统排查：1. 检查尿素液位(低于10%触发报警)；2. 检查尿素质量(GB29518标准)；3. 读取故障码；4. 检查尿素管路是否泄漏或结晶。尿素正常消耗为柴油的3%-5%。消耗偏高可能原因：排温传感器故障、喷嘴雾化不良、SCR催化器效率下降。', '检查尿素液位和质量→读取故障码→定位问题。尿素正常消耗为柴油的3%-5%。', 'DOC20260704006', '排放系统', '["SCR","尿素","国六","排放"]', 'PUBLISHED', 0.9080, '{"vehicleModels":["J7国六","J6P国六"],"difficulty":"较高"}', 'NOT_SYNCED', NULL, '2026-07-02 09:00:00', '2026-07-05 14:00:00'),

('QA20260705006', '车队管理系统如何批量导入车辆？', '批量导入：1. 准备Excel模板(VIN/车牌/ICCID/车型/车队)；2. 平台→车辆管理→批量导入→上传；3. 系统自动校验；4. 一键导入并下发配置；5. 等待激活(1-2小时)。VIN码17位，ICCID 20位，单次最多500台。', '下载模板→填写VIN/ICCID→上传校验→一键导入→等待激活。', 'DOC20260703005', '平台操作', '["批量导入","车辆管理","车队"]', 'PUBLISHED', 0.8860, '{"vehicleModels":["全系"],"difficulty":"简单"}', 'NOT_SYNCED', NULL, '2026-07-05 16:00:00', '2026-07-06 10:00:00');

